package com.bank.ownership.accounts;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.logging.Logger;

// SOLE owner of accounts data. All its invariants run here; nobody else writes accounts.
public class AccountService {
    private static final Logger log = Logger.getLogger(AccountService.class.getName());
    private final Map<String, BigDecimal> balance = new HashMap<>();
    private final Map<String, BigDecimal> overdraft = new HashMap<>();
    private Consumer<String> balanceChangedPublisher = e -> {}; // event out

    public void open(String id, BigDecimal bal, BigDecimal od) { balance.put(id, bal); overdraft.put(id, od); }
    public void onBalanceChanged(Consumer<String> publisher) { this.balanceChangedPublisher = publisher; }

    // The controlled interface. Enforces overdraft rule + audit — cannot be bypassed.
    public void debit(String accountId, BigDecimal amount) {
        BigDecimal current = balance.get(accountId);
        BigDecimal limit = overdraft.get(accountId);
        BigDecimal after = current.subtract(amount);
        if (after.compareTo(limit.negate()) < 0) {              // invariant check
            throw new OverdraftException("Debit breaches overdraft limit for " + accountId);
        }
        balance.put(accountId, after);
        log.info(() -> "AUDIT debit " + amount + " on " + accountId + " → " + after); // audit invariant
        balanceChangedPublisher.accept(accountId + "=" + after); // publish event to replicas
    }
    public BigDecimal balanceOf(String accountId) { return balance.get(accountId); }
}
