package com.bank.ownership.loans;

import java.util.HashMap;
import java.util.Map;

// Read-only replicated view owned by Loans. Updated by events; Loans can NEVER write accounts.
public class BalanceReplica {
    private final Map<String, String> view = new HashMap<>();
    public void apply(String event) {            // "SAV2001=950000"
        String[] p = event.split("=");
        view.put(p[0], p[1]);
    }
    public String read(String accountId) { return view.getOrDefault(accountId, "unknown"); }
}
