package com.bank.ownership.loans;

import com.bank.ownership.accounts.AccountService;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Consumer. Uses the Accounts API for writes and a replica for fast local reads.
// It has NO direct access to the accounts table.
public class LoanService {
    private static final Logger log = Logger.getLogger(LoanService.class.getName());
    private final AccountService accounts;   // controlled interface
    private final BalanceReplica replica;    // read-only local view

    public LoanService(AccountService accounts, BalanceReplica replica) {
        this.accounts = accounts; this.replica = replica;
    }
    // Disburse by calling the owner's API — the overdraft + audit rules ALWAYS run.
    public void disburse(String accountId, BigDecimal amount) {
        log.info(() -> "Loan disbursement via Accounts API for " + accountId);
        accounts.debit(accountId, amount);    // cannot bypass invariants
    }
    public String quickBalance(String accountId) { return replica.read(accountId); }
}
