package com.bank.ownership;

import com.bank.ownership.accounts.AccountService;
import com.bank.ownership.accounts.OverdraftException;
import com.bank.ownership.loans.BalanceReplica;
import com.bank.ownership.loans.LoanService;
import java.math.BigDecimal;
import java.util.logging.*;

public class OwnershipDemo {
    private static final Logger log = Logger.getLogger(OwnershipDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }
    public static void main(String[] args) {
        AccountService accounts = new AccountService();   // sole owner
        accounts.open("SAV2001", new BigDecimal("1000000"), BigDecimal.ZERO);

        BalanceReplica replica = new BalanceReplica();
        accounts.onBalanceChanged(replica::apply);         // events update the replica
        LoanService loans = new LoanService(accounts, replica);

        log.info("=== Owned path: Loans goes through Accounts API (rules enforced) ===");
        loans.disburse("SAV2001", new BigDecimal("50000"));
        log.info(() -> "Loans quick read from replica: SAV2001=" + loans.quickBalance("SAV2001"));

        log.info("=== Invariant enforced: cannot breach overdraft via the API ===");
        try {
            loans.disburse("SAV2001", new BigDecimal("2000000")); // would go far below 0
        } catch (OverdraftException e) {
            log.warning(() -> "Blocked by owner's invariant: " + e.getMessage());
        }
        log.info("Shared-table write would have bypassed this rule and corrupted the balance");
    }
}

